<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Card Verification</title><style>body{margin:0;background:#f7f5ef;font-family:Arial,sans-serif;color:#102a4c}.wrap{max-width:560px;margin:8vh auto;padding:32px;background:#fff;border:1px solid #d9d5cc;border-top:6px solid #c99a3d;border-radius:14px;box-shadow:0 12px 35px #102a4c18}.brand{text-transform:uppercase;letter-spacing:2px;color:#c99a3d;font-weight:bold;font-size:13px}.ok{display:inline-block;margin:16px 0 22px;padding:6px 12px;border-radius:20px;background:#e7f6ed;color:#16834b;font-weight:bold;font-size:12px}.row{display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid #e8e5de}.label{font-size:11px;color:#6d7480;text-transform:uppercase}.value{font-weight:bold}</style></head><body><main class="wrap"><div class="brand">Daniyal Group of Colleges</div><h1>Student Card Verification</h1><div class="ok">{{ $card->status === 'active' ? 'VALID' : strtoupper($card->status) }}</div><div class="row"><span class="label">Student Name</span><span class="value">{{ $card->student->full_name }}</span></div><div class="row"><span class="label">Student ID</span><span class="value">{{ $card->card_number }}</span></div><div class="row"><span class="label">Program</span><span class="value">{{ $card->student->course?->name ?? '—' }}</span></div><div class="row"><span class="label">Campus</span><span class="value">{{ $card->student->campus?->name ?? '—' }}</span></div><div class="row"><span class="label">Valid Until</span><span class="value">{{ optional($card->valid_until)->format('d M Y') ?? '—' }}</span></div></main></body></html>
